const fs = require('fs');
const path = require('path');

console.log('🔄 Merging Prisma schema files...');

const schemaDir = path.join(__dirname, '..', 'prisma', 'schema');
const outputFile = path.join(__dirname, '..', 'prisma', 'schema.prisma');

// Base schema content with generator and datasource
const baseSchema = `// This file is auto-generated by scripts/merge-prisma.js
// Do not edit this file directly. Edit the files in prisma/schema/ instead.

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

`;

try {
  // Read all .prisma files from the schema directory
  const files = fs
    .readdirSync(schemaDir)
    .filter((file) => file.endsWith('.prisma'));

  console.log(`📁 Found ${files.length} schema files:`);
  files.forEach((file) => console.log(`   - ${file}`));

  let mergedContent = baseSchema;

  // Read and merge each schema file
  files.forEach((file) => {
    const filePath = path.join(schemaDir, file);
    const content = fs.readFileSync(filePath, 'utf8');

    // Remove any generator/datasource blocks from individual files
    const cleanContent = content
      .replace(/generator\s+\w+\s*\{[^}]*\}/g, '')
      .replace(/datasource\s+\w+\s*\{[^}]*\}/g, '')
      .trim();

    if (cleanContent) {
      mergedContent += `\n// From ${file}\n${cleanContent}\n`;
    }
  });

  // Write the merged schema
  fs.writeFileSync(outputFile, mergedContent);

  console.log('✅ Schema files merged successfully!');
  console.log(`📄 Output: ${outputFile}`);
} catch (error) {
  console.error('❌ Error merging schema files:', error.message);
  process.exit(1);
}
